<script setup lang="ts">
import { computed, ref } from "vue";
import type { LibraryItem, RankedCitationItem } from "../../api/literatureSearch";
import { DEFAULT_PAGE_SIZE } from "../../composables/useLiteratureResults";
interface Props { resultId?: number; items: readonly RankedCitationItem[]; selectedPmids?: readonly string[]; loading: boolean; updating: Readonly<Record<string, boolean>>; currentPage: number; pageSize?: number; totalPages: number; filteredTotal: number; hasPrevious: boolean; hasNext: boolean }
const props = withDefaults(defineProps<Props>(), { pageSize: DEFAULT_PAGE_SIZE });
const emit = defineEmits<{ previousPage: []; nextPage: []; goToPage: [number]; toggleReadingPlan: [string, boolean]; toggleRead: [string, boolean]; toggleSelection: [string, boolean]; libraryItemUpdated: [string, LibraryItem]; showScoreExplanation: [string] }>();
const expandedAbstracts = ref(new Set<string>());
const pages = computed(() => { const start = Math.max(1, props.currentPage - 2); const end = Math.min(props.totalPages, props.currentPage + 2); return Array.from({ length: end - start + 1 }, (_, index) => start + index); });
const range = computed(() => ({ start: props.filteredTotal ? (props.currentPage - 1) * props.pageSize + 1 : 0, end: Math.min(props.currentPage * props.pageSize, props.filteredTotal) }));
const authorText = (authors: readonly string[]) => authors.length > 3 ? `${authors.slice(0, 3).join(", ")} 等 ${authors.length} 位` : authors.join(", ") || "作者未提供";
const indexOf = (index: number) => (props.currentPage - 1) * props.pageSize + index + 1;
const pubmed = (pmid: string) => /^\d+$/.test(pmid) ? `https://pubmed.ncbi.nlm.nih.gov/${pmid}/` : null;
const metric = (entry: RankedCitationItem) => entry.journal_metric?.latest;
function toggleAbstract(pmid: string) { const next = new Set(expandedAbstracts.value); next.has(pmid) ? next.delete(pmid) : next.add(pmid); expandedAbstracts.value = next; }
</script>

<template>
  <section class="results" aria-label="检索结果">
    <header v-if="filteredTotal" class="results-navigation"><p class="range-note">筛选后 {{ filteredTotal }} 篇　·　{{ range.start }}–{{ range.end }} / {{ filteredTotal }}</p><div v-if="totalPages > 1" class="navigation-controls"><button aria-label="上一页" :disabled="loading || !hasPrevious" @click="emit('previousPage')">‹ 上一页</button><span>第 {{ currentPage }} 页，共 {{ totalPages }} 页</span><button aria-label="下一页" :disabled="loading || !hasNext" @click="emit('nextPage')">下一页 ›</button></div></header>
    <div v-if="loading" class="loading">正在读取检索结果…</div><p v-else-if="!items.length" class="empty">当前筛选条件下没有结果，请调整筛选条件。</p>
    <ol v-else><li v-for="(entry, index) in items" :key="entry.item.pmid" class="result-row">
      <input type="checkbox" :aria-label="`选择 ${entry.item.title || entry.item.pmid}`" :checked="selectedPmids?.includes(entry.item.pmid)" @change="emit('toggleSelection', entry.item.pmid, ($event.target as HTMLInputElement).checked)"><span class="number">{{ indexOf(index) }}</span>
      <article><h3>{{ entry.item.title || "标题未提供" }}</h3><p class="meta">{{ authorText(entry.item.authors) }}　·　{{ entry.item.journal || "期刊未提供" }}　·　{{ entry.item.year || "—" }}　·　PMID {{ entry.item.pmid }}</p>
        <div class="reading-signals badges"><span v-for="type in entry.item.publication_types.slice(0, 2)" :key="type">{{ type }}</span><span v-if="entry.item.verified" class="verified">PubMed 已核实</span></div>
        <div v-if="metric(entry)" class="journal-signals badges"><span v-if="metric(entry)?.impact_factor?.value != null" class="if">IF {{ metric(entry)?.impact_factor?.value }} · {{ metric(entry)?.impact_factor?.year }}</span><span v-if="metric(entry)?.jcr?.best_quartile" class="jcr">JCR {{ metric(entry)?.jcr?.best_quartile }} · {{ metric(entry)?.jcr?.year }}</span><span v-if="metric(entry)?.wos?.indexes?.length" class="wos">{{ metric(entry)?.wos?.indexes.join('/') }} · {{ metric(entry)?.wos?.year }}</span><span v-if="metric(entry)?.cas?.quartile" class="cas">中科院{{ metric(entry)?.cas?.quartile }} · {{ metric(entry)?.cas?.year }}</span></div>
        <div class="abstract-disclosure"><p><b>AI摘要要点：</b>{{ entry.item.abstract ? (expandedAbstracts.has(entry.item.pmid) ? entry.item.abstract : `${entry.item.abstract.slice(0, 105)}${entry.item.abstract.length > 105 ? '…' : ''}`) : "摘要不可用" }}</p><button v-if="entry.item.abstract" type="button" @click="toggleAbstract(entry.item.pmid)">{{ expandedAbstracts.has(entry.item.pmid) ? "收起摘要" : "展开摘要" }}</button></div>
        <p class="article-signals"><span class="relevance-signal">{{ entry.score_summary?.relevance.score != null ? `相关度 ${Math.round(entry.score_summary.relevance.score)}` : "相关度暂不可用" }}</span><span v-if="entry.score_summary?.popularity.score != null">🔥 近期热度 {{ Math.round(entry.score_summary.popularity.score) }}</span><span v-if="entry.score_summary?.cited_by_count != null">被引 {{ entry.score_summary.cited_by_count }}</span><button v-if="entry.score_summary" @click="emit('showScoreExplanation', entry.item.pmid)">查看依据⌄</button></p>
      </article>
      <aside class="record-actions--rail record-actions--horizontal"><div class="state"><span :class="{ read: entry.state?.read_status === 'read' }">{{ entry.state?.read_status === 'read' ? '✓ 已读' : entry.state?.read_status === 'reading' ? '• 阅读中' : '○ 未读' }}</span><span v-if="entry.state?.is_key" class="key">★ 重点</span></div><div class="actions"><button class="reading-plan-action" :class="{ planned: entry.state?.in_reading_plan || entry.state?.saved }" :disabled="updating[entry.item.pmid]" @click="emit('toggleReadingPlan', entry.item.pmid, !(entry.state?.in_reading_plan || entry.state?.saved))">{{ entry.state?.in_reading_plan || entry.state?.saved ? '✓ 已在阅读计划' : '＋ 加入阅读计划' }}</button><a v-if="pubmed(entry.item.pmid)" :href="pubmed(entry.item.pmid)!" target="_blank" rel="noopener noreferrer">访问 PubMed ↗</a><button class="row-action" @click="emit('toggleRead', entry.item.pmid, entry.state?.read_status !== 'read')">{{ entry.state?.read_status === 'read' ? '标记未读' : '标记已读' }}</button></div></aside>
    </li></ol>
    <nav v-if="filteredTotal > 0 && totalPages > 1" class="pagination" aria-label="结果分页"><button :disabled="loading || !hasPrevious" @click="emit('previousPage')">‹ 上一页</button><button v-for="page in pages" :key="page" :class="{ current: page === currentPage }" :disabled="page === currentPage" @click="emit('goToPage', page)">{{ page }}</button><button :disabled="loading || !hasNext" @click="emit('nextPage')">下一页 ›</button></nav>
  </section>
</template>

<style scoped>
.results{background:#fff}.results-navigation{display:flex;align-items:center;justify-content:space-between;min-height:40px;padding:0 16px;border-bottom:1px solid #dfe8f4;color:#536e91;font-size:11px}.range-note{margin:0}.navigation-controls{display:flex;align-items:center;gap:8px}.navigation-controls button{height:26px;padding:0 8px;border:1px solid #d3e0f2;border-radius:5px;background:#fff;color:#1754ae}.results ol{margin:0;padding:0;list-style:none}.result-row{display:grid;grid-template-columns:18px 28px minmax(0,1fr) 176px;gap:8px;min-height:140px;box-sizing:border-box;padding:10px 16px;border-bottom:1px solid #dfe8f4}.result-row:hover{background:#fbfdff}.result-row>input{width:14px;height:14px;margin-top:4px;accent-color:#1762fa}.number{display:grid;width:26px;height:26px;place-items:center;border-radius:50%;background:#1762fa;color:#fff;font-size:11px;font-weight:750}.result-row article{min-width:0}.result-row h3{display:-webkit-box;margin:0;overflow:hidden;color:#071d3d;font-size:15px;line-height:18px;font-weight:720;-webkit-box-orient:vertical;-webkit-line-clamp:2}.meta{margin:3px 0;color:#536e91;font-size:10px;line-height:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.badges{display:flex;align-items:center;gap:4px;min-height:19px;overflow:hidden}.badges span{padding:2px 6px;border-radius:4px;background:#edf4ff;color:#0759f9;font-size:9px;white-space:nowrap}.reading-signals{float:left;margin-right:4px}.badges .verified{color:#146b56;background:#eaf8f3}.badges .if{background:#fff1e7;color:#ed6a16}.badges .jcr{background:#e9f8f1;color:#07845f}.badges .wos{background:#e8f6ff;color:#0878a7}.badges .cas{background:#f1edff;color:#6c43c4}.abstract-disclosure{display:flex;clear:both;align-items:center;min-width:0}.abstract-disclosure p{margin:2px 0;color:#38597f;font-size:10px;line-height:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.abstract-disclosure button,.article-signals button{flex:none;border:0;background:transparent;color:#0759f9;font-size:10px}.article-signals{display:flex;gap:10px;margin:0;color:#16815e;font-size:10px;line-height:14px}.record-actions--rail{display:flex;flex-direction:column;padding-left:14px;border-left:1px solid #e2eaf4}.state{display:flex;gap:12px;color:#527097;font-size:10px}.state .read{color:#07865f}.state .key{color:#ed7b12}.actions{display:flex;flex-direction:column;align-items:stretch;gap:5px;margin-top:10px}.actions button,.actions a{height:28px;box-sizing:border-box;width:100%;padding:0 9px;border:1px solid #cbdcf7;border-radius:5px;background:#fff;color:#0759f9;font-size:10px;line-height:26px;text-align:center;text-decoration:none;white-space:nowrap}.actions button.planned{background:#eef4ff}.loading,.empty{margin:0;padding:40px;text-align:center;color:#667e9f}.pagination{display:flex;justify-content:center;gap:5px;padding:12px}.pagination button{height:30px;border:1px solid #d3e0f2;border-radius:5px;background:#fff;color:#34577f}.pagination button.current{background:#1762fa;color:#fff}.pagination button:disabled{opacity:.55}@media(max-width:900px){.result-row{grid-template-columns:18px 28px 1fr;height:auto}.record-actions--rail{grid-column:3;padding:7px 0 0;border:0;border-top:1px solid #edf1f7}.actions{align-items:flex-start}.actions button,.actions a{width:auto;min-width:132px}}
</style>
